import itertools
L=np.log(1+t)**2
best=[]
Pf={'1':np.ones_like(P),'P':P,'P2':P**2,'sqP':np.sqrt(P),'P3':P**3}
for w in np.arange(0.05,3.01,0.05):
  for tf,tv in [('sin',np.sin(w*t)),('cos',np.cos(w*t)),('exp',np.exp(-w*t)),('expp',np.exp(w*t/10))]:
    for pa,pv in Pf.items():
      for pb,pv2 in Pf.items():
        if pb<=pa: continue
        X=np.column_stack([L,pv*tv,pv2])
        c=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
        r=dP_dt-X@c
        best.append((np.mean(r**2)/np.var(dP_dt),w,tf,pa,pb,c))
best.sort(key=lambda x:x[0])
for b in best[:6]: print(b)
